        emit(
            &format!("trim_outcome_{}", mode.to_lowercase()),
            &[
                ("mode", q(mode)),
                ("nodes", q(&node_list)),
                ("leader", n(0)),
                ("stage", q("no_leader")),
            ],
        );
        return;
    }

    // One entry appended on the leader, propagated to every server.
    ops.get_mut(&preferred).unwrap().append(TestEntry(7)).unwrap();
    let mut all_decided = false;
