        .get_mut(&preferred)
        .unwrap()
        .snapshot(Some(decided_before), true);
    let compacted_after_snapshot = ops.get(&preferred).unwrap().get_compacted_idx();
    let snapshot_advanced = compacted_after_snapshot > compacted_after_explicit;

    emit(
        &format!("trim_outcome_{}", mode.to_lowercase()),
        &[
            ("mode", q(mode)),
            ("nodes", q(&node_list)),
            ("leader", n(leader_pid as usize)),
